:4,"video_url":"https://www.youtube.com/watch?v=mFIQVViF0PU","video_provider":"youtube","video_duration":"64:08","video_thumbnail_url":null,"has_transcript":false,"is_published":true}]'::jsonb) as x(id text, course_id text, module_id text, source_path text, title text, summary text, lesson_kind text, sort_order integer, video_url text, video_provider text, video_duration text, video_thumbnail_url text, has_transcript boolean, is_published boolean)
on conflict (id) do update set title=excluded.title, summary=excluded.summary, sort_order=excluded.sort_order, video_url=excluded.video_url, video_provider=excluded.video_provider, video_duration=excluded.video_duration, is_published=excluded.is_published, updated_at=now();

do $$
declare actual integer;
begin
  select count(*) into actual from public.course_lessons where course_id='imperio-agentico' and source_path like 'legacy-curated/%' and summary<>'';
  if actual <> 67 then raise exception 'Expected 67 reviewed legacy lessons, found %', actual; end if;
end $$;
